package phpgen

import (
	"fmt"
	"sort"
	"strings"

	"github.com/hostingpal/whm-api-client/tools/api-map/internal/effective"
)

// Marker identifies generated files; files without it are never touched.
const Marker = "Generated by tools/api-map from the pinned API map and docs/api/overlay; do not edit."

const rootNamespace = `HostingPal\WhmApiClient`

type writer struct{ b strings.Builder }

func (w *writer) line(s string) {
	w.b.WriteString(s)
	w.b.WriteByte('\n')
}

func (w *writer) doc(indent, text string) {
	for _, l := range wrap(escapeDoc(text), lineWidth-len(indent)-3) {
		w.line(indent + " * " + l)
	}
}

// paramDoc writes one "@param <type> $name" tag. The tag head always stays on a
// single line. Legacy heads exceeding lineWidth use the parameter's plain type
// (string|list<string> for list encodings). Collection heads retain precise literal
// types even when overlong: preserving their enum contract takes precedence over
// the plain-type fallback. Only the description wraps, with continuation lines
// indented four spaces after the asterisk.
func (w *writer) paramDoc(indent string, p effective.Param, description string) {
	// Enum literals come from the pinned documents and could contain "*/".
	docType := escapeDoc(paramDocType(p))
	head := func(t string) string { return indent + " * @param " + t + " $" + p.PHP }
	if p.Collection == nil && p.Records == nil && len(head(docType)) > lineWidth {
		docType = p.PHPType
		if isMultiple(p.Encoding) {
			docType = "string|list<string>"
			if p.Encoding == "suffix-numbered-scalar" {
				docType = "string|int|list<string|int>"
			}
		}
		if !p.Required {
			docType += "|null"
		}
	}
	current := head(docType)
	continuation := indent + " *     "
	for _, word := range strings.Fields(escapeDoc(description)) {
		if len(current)+1+len(word) > lineWidth {
			w.line(current)
			current = continuation + word
			continue
		}
		current += " " + word
	}
	w.line(current)
}

// docTag writes a tag line whose type may span lines (multi-line shapes).
func (w *writer) docTag(indent, text string) {
	for _, l := range strings.Split(text, "\n") {
		w.line(strings.TrimRight(indent+" * "+l, " "))
	}
}

// typeAlias wraps an overlong single-line generic after its outer opening
// bracket. The type's contents stay intact, including quoted literals and keys.
func (w *writer) typeAlias(name string, spec effective.TypeSpec) {
	head := "@phpstan-type " + name + " "
	docType := shape(spec, "")
	if (spec.Type == "map" || spec.Type == "list") && !strings.Contains(docType, "\n") &&
		len(head)+len(docType)+3 > lineWidth {
		prefix, contents, _ := strings.Cut(docType, "<")
		docType = prefix + "<\n    " + contents
	}
	w.docTag("", head+docType)
}

// families lists every generated family. Both handles use their family's
// accessor trait, so each trait is rendered even when it has no groups.
var families = []string{"uapi", "whm1"}

// FamilyDirs returns the repository folders that hold generated PHP; stale
// generated files are looked for in these folders.
func FamilyDirs() []string {
	dirs := make([]string, len(families))
	for i, family := range families {
		dirs[i] = "src/Api/" + familyDir(family)
	}
	return dirs
}

// Render returns generated file contents keyed by repository-relative path.
func Render(result effective.Result) map[string][]byte {
	files := map[string][]byte{}
	byFamily := map[string][]effective.Group{}
	for _, group := range result.Groups {
		dir := familyDir(group.Family)
		files["src/Api/"+dir+"/"+group.Class+".php"] = []byte(groupClass(group))
		files["src/Api/"+dir+"/Spec/"+group.Class+"Spec.php"] = []byte(specClass(group))
		byFamily[group.Family] = append(byFamily[group.Family], group)
	}
	for _, family := range families {
		dir := familyDir(family)
		files["src/Api/"+dir+"/"+dir+"Groups.php"] = []byte(groupsTrait(family, byFamily[family]))
	}
	files["docs/api/coverage.md"] = []byte(coverage(result))
	return files
}

func familyDir(family string) string {
	if family == "uapi" {
		return "Uapi"
	}
	return "Whm"
}

func header(w *writer, namespace string) {
	w.line("<?php")
	w.line("")
	w.line("declare(strict_types=1);")
	w.line("")
	w.line("namespace " + namespace + ";")
	w.line("")
}

func lifecycle(family string) string {
	if family == "uapi" {
		return "Each method executes one request immediately for this handle's cPanel account, through direct cPanel " +
			"access or WHM according to the configured credentials, with a single attempt and no retries. The handle " +
			"clears responseMeta() before every attempt and records the envelope snapshot before API or payload errors."
	}
	return "Each method executes one WHM API 1 request immediately with a single attempt and no retries. The handle " +
		"clears responseMeta() before every attempt and records the envelope snapshot before API or payload errors."
}

func resultSpec(op effective.Operation) *effective.TypeSpec {
	if op.Returns == nil {
		return nil
	}
	if op.Unwrap == "" {
		return op.Returns
	}
	for _, field := range op.Returns.Fields {
		if field.Name == op.Unwrap {
			spec := field.Spec
			return &spec
		}
	}
	return &effective.TypeSpec{Type: "mixed"}
}

// docReturn renders the PHPStan return type; an optional payload adds null.
func docReturn(op effective.Operation, spec effective.TypeSpec) string {
	if isArrayLike(spec) {
		if op.OptionalPayload && !spec.Nullable {
			return op.Alias + "|null"
		}
		return op.Alias
	}
	return shape(returnSpec(op, spec), "")
}

// returnSpec is the result spec as the method returns it: an optional payload
// makes it nullable, because no data yields null.
func returnSpec(op effective.Operation, spec effective.TypeSpec) effective.TypeSpec {
	if op.OptionalPayload {
		spec.Nullable = true
	}
	return spec
}

func groupClass(g effective.Group) string {
	namespace := rootNamespace + `\Api\` + familyDir(g.Family)
	w := &writer{}
	header(w, namespace)
	uses := []string{"Closure", namespace + `\Spec\` + g.Class + "Spec", rootNamespace + `\Exception\ApiException`}
	for _, op := range publicMethods(g) {
		if op.Returns != nil {
			uses = append(uses, rootNamespace+`\Exception\PayloadMismatchException`)
		}
		for _, p := range op.Params {
			if isMultiple(p.Encoding) || p.RejectEmpty || p.Input != nil {
				uses = append(uses, "InvalidArgumentException")
			}
			if redactArgument(p) {
				uses = append(uses, "SensitiveParameter")
			}
		}
	}
	for _, op := range g.Operations {
		if op.MultipartUploads != nil || op.MultipartUpload != nil || op.MultipartUploadFamily != nil {
			uses = append(uses, "HostingPal\\WhmApiClient\\Upload", "InvalidArgumentException")
		}
	}
	for _, use := range uniqueSorted(uses) {
		w.line("use " + use + ";")
	}
	w.line("")
	w.line("/**")
	// The marker leads every docblock so an unbounded description can never
	// push it past the lines the generator scans to recognise its own files.
	w.doc("", Marker)
	w.line(" *")
	w.doc("", g.Description)
	w.line(" *")
	w.doc("", lifecycle(g.Family))
	aliases := false
	for _, op := range g.Operations {
		spec := resultSpec(op)
		if spec == nil || !isArrayLike(*spec) {
			continue
		}
		if !aliases {
			w.line(" *")
			aliases = true
		}
		w.typeAlias(op.Alias, *spec)
	}
	for _, op := range g.Operations {
		if d := op.JSONBody; d != nil {
			w.line(" *")
			w.docTag("", "@phpstan-type "+d.Alias+" "+inputShape(d.Schema, ""))
		}
	}
	for _, op := range publicMethods(g) {
		for _, p := range op.Params {
			if p.Encoding == "json" && p.Input != nil {
				w.line(" *")
				w.docTag("", "@phpstan-type "+p.DocType+" "+inputShape(*p.Input, ""))
			}
			if p.Records == nil {
				continue
			}
			w.line(" *")
			w.line(" * @phpstan-type " + p.Records.Alias + " array{")
			for _, f := range p.Records.Fields {
				optional := ""
				if !f.Required {
					optional = "?"
				}
				w.line(" *     " + f.PHP + optional + ": " + f.Type + ",")
			}
			w.line(" * }")
		}
	}
	w.line(" */")
	w.line("final readonly class " + g.Class)
	w.line("{")
	w.line("    /**")
	w.line("     * Bind the group to its handle's operation runner.")
	w.line("     *")
	w.line("     * @param Closure(array<mixed>, array<string, mixed>): mixed $run")
	w.line("     * @internal Obtain this group through the handle's accessor.")
	w.line("     */")
	w.line("    public function __construct(private Closure $run)")
	w.line("    {")
	w.line("    }")
	for _, op := range publicMethods(g) {
		w.line("")
		method(w, g, op)
	}
	w.line("}")
	return w.b.String()
}

func paramDocType(p effective.Param) string {
	if p.Required {
		return p.DocType
	}
	return p.DocType + "|null"
}

func paramNative(p effective.Param) string {
	if p.Required {
		return p.PHPType
	}
	if strings.Contains(p.PHPType, "|") {
		return p.PHPType + "|null"
	}
	return "?" + p.PHPType
}

func method(w *writer, g effective.Group, op effective.Operation) {
	const indent = "    "
	ret := resultSpec(op)
	w.line(indent + "/**")
	// JSON-body notes carry operation-specific whole-configuration obligations.
	// Put them before source prose without changing legacy documentation order.
	if op.JSONBody != nil {
		for _, note := range op.Notes {
			w.doc(indent, note.Label+": "+note.Text)
			w.line(indent + " *")
		}
	}
	w.doc(indent, op.Summary)
	if op.Description != "" {
		w.line(indent + " *")
		w.doc(indent, op.Description)
	}
	if op.JSONBody == nil {
		for _, note := range op.Notes {
			w.line(indent + " *")
			w.doc(indent, note.Label+": "+note.Text)
		}
	}
	if op.OptionalPayload && ret != nil {
		w.line(indent + " *")
		w.doc(indent, "Returns null when the server sends no data.")
	}
	w.line(indent + " *")
	identity := "API-map identity: " + op.VariantID + " (wire name " + op.Function
	if op.Subcategory != "" {
		identity += "; " + op.Subcategory
	}
	w.doc(indent, identity+").")
	w.line(indent + " *")
	multi := false
	scalarMulti := false
	namedMap := false
	records := false
	omitEmpty := false
	rejectEmpty := false
	for _, p := range op.Params {
		description := p.Description
		if !p.Required {
			description = strings.TrimSpace(description + " Null omits it.")
		}
		if p.Input != nil && p.Encoding == "json" {
			description = strings.TrimSpace(description + " Validated JSON value in one form field; serialized once before form encoding.")
		} else if p.Input != nil {
			description = strings.TrimSpace(description + " Validated whole JSON body. Secrets belong in the body, not URL query fields. Direct routes only.")
			multi = true
		}
		if p.OmitEmpty {
			description = strings.TrimSpace(description + " Empty list omits it.")
		}
		if p.Records != nil {
			for _, f := range p.Records.Fields {
				description += " " + f.PHP + ": " + f.Description
			}
		}
		w.paramDoc(indent, p, description)
		records = records || p.Records != nil
		omitEmpty = omitEmpty || p.OmitEmpty
		rejectEmpty = rejectEmpty || p.RejectEmpty
		multi = multi || isMultiple(p.Encoding)
		namedMap = namedMap || (p.Collection != nil && p.Collection.Kind == "map")
		scalarMulti = scalarMulti || p.Encoding == "suffix-numbered-scalar" || p.Collection != nil || p.Records != nil
	}
	if ret != nil {
		w.docTag(indent, "@return "+docReturn(op, *ret))
	}
	w.line(indent + " * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.")
	if ret != nil && op.Outcome == "flag" {
		w.line(indent + " * @throws PayloadMismatchException If the API envelope reported success but the payload differs from the contract;")
		w.line(indent + " *     the operation may already have changed state; do not retry automatically.")
	} else if ret != nil {
		w.line(indent + " * @throws PayloadMismatchException If the envelope was accepted but the payload differs from the contract;")
		w.line(indent + " *     the outcome is not checked.")
	}
	jsonField := false
	for _, p := range op.Params {
		jsonField = jsonField || p.Encoding == "json"
	}
	if jsonField {
		w.line(indent + " * @throws InvalidArgumentException If a structured JSON field is invalid; no request is sent.")
	} else if op.JSONBody != nil {
		w.line(indent + " * @throws InvalidArgumentException If the whole JSON body is invalid, root routing names are reserved,")
		w.line(indent + " *     or this account handle uses the unsupported WHM bridge.")
	} else if op.MultipartUpload != nil {
		w.line(indent + " * @throws InvalidArgumentException If the upload or multipart fields are invalid; no retry occurs.")
	} else if op.MultipartUploads != nil || op.MultipartUploadFamily != nil {
		w.line(indent + " * @throws InvalidArgumentException If uploads are empty, keyed, invalid, or this handle uses the WHM bridge.")
	} else if rejectEmpty {
		w.line(indent + " * @throws InvalidArgumentException If an explicit target is absent, blank, zero, or an invalid string list.")
	} else if multi {
		if records {
			w.line(indent + " * @throws InvalidArgumentException If records are empty, nonsequential, contain unknown or missing fields,")
			w.line(indent + " *     invalid field types or expanded names; other list/map inputs retain their declared validation rules.")
		} else if namedMap {
			w.line(indent + " * @throws InvalidArgumentException If map keys, values, empty policy, or expanded names are invalid;")
			w.line(indent + " *     list inputs must be nonempty, sequential, and contain supported values.")
		} else if omitEmpty {
			w.line(indent + " * @throws InvalidArgumentException If a non-omittable list argument is empty,")
			w.line(indent + " *     or any list is keyed or contains non-strings.")
		} else if scalarMulti {
			w.line(indent + " * @throws InvalidArgumentException If a list argument is empty, keyed, or contains an unsupported value.")
		} else {
			w.line(indent + " * @throws InvalidArgumentException If a list argument is empty or contains non-strings.")
		}
	}
	w.line(indent + " * @see " + op.SeeURL)
	w.line(indent + " */")
	signature(w, op, ret)
	body(w, g, op, ret)
	w.line(indent + "}")
}

// Collection contents are always trace-protected, independently of transport secrecy.
func redactArgument(p effective.Param) bool {
	return p.Sensitive || p.Collection != nil || p.Records != nil
}

func signature(w *writer, op effective.Operation, ret *effective.TypeSpec) {
	native := "void"
	if ret != nil {
		native = nativeType(returnSpec(op, *ret))
	}
	parts := make([]string, len(op.Params))
	sensitive := false
	for i, p := range op.Params {
		parts[i] = paramNative(p) + " $" + p.PHP
		if !p.Required {
			parts[i] += " = null"
		}
		sensitive = sensitive || redactArgument(p)
	}
	single := "    public function " + op.PHPName + "(" + strings.Join(parts, ", ") + "): " + native
	if !sensitive && len(single) <= lineWidth {
		w.line(single)
		w.line("    {")
		return
	}
	w.line("    public function " + op.PHPName + "(")
	for i, p := range op.Params {
		if redactArgument(p) {
			w.line("        #[SensitiveParameter]")
		}
		w.line("        " + parts[i] + ",")
	}
	w.line("    ): " + native + " {")
}

func body(w *writer, g effective.Group, op effective.Operation, ret *effective.TypeSpec) {
	constant := g.Class + "Spec::" + op.Constant
	arguments := make([]string, len(op.Params))
	for i, p := range op.Params {
		arguments[i] = phpString(p.PHP) + " => $" + p.PHP
	}
	call := "($this->run)(" + constant + ", [" + strings.Join(arguments, ", ") + "])"
	prefix := "        "
	if ret != nil {
		prefix = "        $result = "
		varLine := "        /** @var " + docReturn(op, *ret) + " $result Validated against " + constant + ". */"
		if len(varLine) <= lineWidth {
			w.line(varLine)
		} else {
			w.line("        /**")
			w.line("         * @var " + docReturn(op, *ret) + " $result")
			w.line("         * Validated against " + constant + ".")
			w.line("         */")
		}
	}
	if len(prefix+call)+1 <= lineWidth {
		w.line(prefix + call + ";")
	} else {
		w.line(prefix + "($this->run)(" + constant + ", [")
		for _, argument := range arguments {
			w.line("            " + argument + ",")
		}
		w.line("        ]);")
	}
	if ret != nil {
		w.line("")
		w.line("        return $result;")
	}
}

func specClass(g effective.Group) string {
	namespace := rootNamespace + `\Api\` + familyDir(g.Family) + `\Spec`
	w := &writer{}
	header(w, namespace)
	w.line("/**")
	w.doc("", Marker)
	w.line(" *")
	w.doc("", "Operation specs for the "+g.Class+" group, consumed by Api\\Engine\\OperationRunner.")
	w.line(" *")
	w.line(" * @internal")
	w.line(" */")
	w.line("final class " + g.Class + "Spec")
	w.line("{")
	for i, op := range publicMethods(g) {
		canonical := ""
		for _, c := range g.Operations {
			if c.ID == op.ID && c.Constant != op.Constant {
				canonical = c.Constant
				break
			}
		}
		if i > 0 {
			w.line("")
		}
		w.line("    public const " + op.Constant + " = [")
		if canonical != "" {
			w.line("        ...self::" + canonical + ",")
		} else {
			w.line("        'function' => " + phpString(op.Function) + ",")
			if op.Module != "" {
				w.line("        'module' => " + phpString(op.Module) + ",")
			}
			w.line("        'method' => " + phpString(op.Method) + ",")
			if op.Body != "" {
				w.line("        'body' => " + phpString(op.Body) + ",")
			}
			w.line("        'outcome' => " + phpString(op.Outcome) + ",")
		}
		if d := op.MultipartUploadFamily; d != nil {
			w.line("        'multipart_upload_family' => [")
			w.line("            'php' => " + phpString(d.PHP) + ",")
			w.line("            'source' => " + phpString(d.Source) + ",")
			w.line("            'routes' => " + phpString(d.Routes) + ",")
			w.line("        ],")
		}
		if d := op.MultipartUpload; d != nil {
			w.line("        'multipart_upload' => [")
			w.line("            'php' => " + phpString(d.PHP) + ",")
			w.line("            'source' => " + phpString(d.Source) + ",")
			w.line("            'text' => " + phpString(d.Text) + ",")
			w.line("        ],")
		}
		if d := op.MultipartUploads; d != nil {
			w.line("        'multipart_uploads' => [")
			w.line("            'php' => " + phpString(d.PHP) + ",")
			w.line("            'prefix' => " + phpString(d.Prefix) + ",")
			w.line(fmt.Sprintf("            'start' => %d,", *d.Start))
			w.line("            'routes' => " + phpString(d.Routes) + ",")
			w.line("            'filename_forbidden' => " + phpString(d.FilenameForbidden) + ",")
			w.line("        ],")
		}
		if d := op.JSONBody; d != nil {
			w.line("        'json_body' => [")
			w.line("            'php' => " + phpString(d.PHP) + ",")
			w.line(fmt.Sprintf("            'required' => %t,", d.Required))
			w.line("            'routes' => " + phpString(d.Routes) + ",")
			w.line("            'schema' => " + inputLiteral(d.Schema, "            ") + ",")
			w.line("        ],")
		}
		if len(op.Params) == 0 || op.MultipartUpload != nil || (op.JSONBody != nil && len(op.Params) == 1) {
			w.line("        'params' => [],")
		} else {
			w.line("        'params' => [")
			for _, p := range op.Params {
				if (p.Input != nil && p.Encoding != "json") || (op.MultipartUploads != nil && p.PHP == op.MultipartUploads.PHP) || (op.MultipartUploadFamily != nil && p.PHP == op.MultipartUploadFamily.PHP) {
					continue
				}
				setting := ""
				if p.OmitEmpty {
					setting = ", 'omit_empty' => true"
				}
				if p.RejectEmpty {
					setting += ", 'reject_empty' => true"
				}
				entry := "            " + phpString(p.PHP) + " => ['name' => " + phpString(p.Wire) +
					", 'encoding' => " + phpString(p.Encoding) + setting + "],"
				if p.Collection == nil && p.Records == nil && p.Encoding != "json" && len(entry) <= lineWidth {
					w.line(entry)
					continue
				}
				w.line("            " + phpString(p.PHP) + " => [")
				w.line("                'name' => " + phpString(p.Wire) + ",")
				w.line("                'encoding' => " + phpString(p.Encoding) + ",")
				if p.Encoding == "json" && p.Input != nil {
					w.line("                'json' => [")
					w.line(fmt.Sprintf("                    'required' => %t,", p.Required))
					w.line("                    'schema' => " + inputLiteral(*p.Input, "                    ") + ",")
					w.line("                ],")
				}
				if c := p.Records; c != nil {
					w.line("                'records' => [")
					w.line(fmt.Sprintf("                    'start' => %d,", c.Start))
					w.line("                    'separator' => " + phpString(c.Separator) + ",")
					w.line("                    'fields' => [")
					for _, f := range c.Fields {
						w.line("                        " + phpString(f.PHP) + " => [")
						w.line("                            'prefix' => " + phpString(f.Prefix) + ",")
						w.line("                            'type' => " + phpString(f.Type) + ",")
						w.line(fmt.Sprintf("                            'required' => %t,", f.Required))
						w.line("                        ],")
					}
					w.line("                    ],")
					w.line("                ],")
				}
				if c := p.Collection; c != nil {
					w.line("                'collection' => [")
					w.line("                    'kind' => " + phpString(c.Kind) + ",")
					w.line("                    'item_type' => " + phpString(c.ItemType) + ",")
					w.line(fmt.Sprintf("                    'allow_scalar' => %t,", *c.AllowScalar))
					w.line("                    'empty' => " + phpString(c.Empty) + ",")
					if c.RejectPrefixedKeys != nil {
						w.line("                    'reject_prefixed_keys' => true,")
					}
					if c.Kind == "indexed" || c.Kind == "map" {
						w.line("                    'prefix' => " + phpString(*c.Prefix) + ",")
					}
					if c.Kind == "indexed" {
						w.line("                    'separator' => " + phpString(*c.Separator) + ",")
						w.line(fmt.Sprintf("                    'start' => %d,", *c.Start))
					}
					w.line("                ],")
				}
				if p.OmitEmpty {
					w.line("                'omit_empty' => true,")
				}
				if p.RejectEmpty {
					w.line("                'reject_empty' => true,")
				}
				w.line("            ],")
			}
			w.line("        ],")
		}
		if canonical == "" {
			if op.Returns == nil {
				w.line("        'returns' => null,")
			} else {
				w.line("        'returns' => " + specLiteralAt(*op.Returns, "        ", len("        'returns' => ")) + ",")
			}
			if op.Rows != "" {
				w.line("        'rows' => " + phpString(op.Rows) + ",")
			}
			if op.Unwrap != "" {
				w.line("        'unwrap' => " + phpString(op.Unwrap) + ",")
			}
			if op.OptionalPayload && op.Returns != nil {
				w.line("        'optional' => true,")
			}
		}
		w.line("    ];")
	}
	w.line("}")
	return w.b.String()
}

func groupsTrait(family string, groups []effective.Group) string {
	dir := familyDir(family)
	w := &writer{}
	header(w, rootNamespace+`\Api\`+dir)
	handle := map[string]string{"uapi": "UapiClient", "whm1": "WhmClient"}[family]
	w.line("/**")
	w.doc("", Marker)
	w.line(" *")
	w.doc("", "Lazy, cached group accessors used by "+handle+"; selecting a group performs no I/O.")
	w.line(" *")
	w.line(" * @internal")
	w.line(" */")
	w.line("trait " + dir + "Groups")
	w.line("{")
	for _, g := range groups {
		w.line("    private ?" + g.Class + " $" + g.Accessor + "Group = null;")
		w.line("")
	}
	for i, g := range groups {
		if i > 0 {
			w.line("")
		}
		w.line("    /**")
		w.doc("    ", "Select the "+g.Name+" operations without making a request.")
		w.line("     *")
		w.doc("    ", g.Description)
		w.line("     */")
		w.line("    public function " + g.Accessor + "(): " + g.Class)
		w.line("    {")
		w.line("        return $this->" + g.Accessor + "Group ??= new " + g.Class + "($this->run(...));")
		w.line("    }")
	}
	w.line("}")
	return w.b.String()
}

func coverage(result effective.Result) string {
	w := &writer{}
	w.line("# Generated API coverage")
	w.line("")
	w.line(Marker)
	w.line("")
	counts := map[string][3]int{}
	for _, g := range result.Groups {
		c := counts[g.Family]
		c[0]++
		c[1] += len(g.Operations)
		counts[g.Family] = c
	}
	for _, e := range result.Excluded {
		family := strings.SplitN(e.ID, ":", 2)[0]
		c := counts[family]
		c[2]++
		counts[family] = c
	}
	label := map[string]string{"uapi": "UAPI", "whm1": "WHM API 1"}
	w.line("| Family | Groups | Generated operations | Excluded |")
	w.line("| --- | ---: | ---: | ---: |")
	for _, family := range []string{"uapi", "whm1"} {
		c := counts[family]
		w.line(fmt.Sprintf("| %s | %d | %d | %d |", label[family], c[0], c[1], c[2]))
	}
	w.line("")
	w.line("## Groups")
	w.line("")
	w.line("| Family | Group | Accessor | Operations |")
	w.line("| --- | --- | --- | ---: |")
	for _, g := range result.Groups {
		handle := map[string]string{"uapi": "uapi()", "whm1": "whm()"}[g.Family]
		w.line(fmt.Sprintf("| %s | %s | `%s->%s()` | %d |", label[g.Family], g.Name, handle, g.Accessor, len(g.Operations)))
	}
	aliases := false
	for _, g := range result.Groups {
		for _, op := range g.Operations {
			if len(op.AdditionalMethods) == 0 {
				continue
			}
			if !aliases {
				w.line("")
				w.line("## Alternate public methods")
				w.line("")
				w.line("These symbols share one canonical operation, route and response contract; counts above do not count aliases.")
				w.line("")
				w.line("| Canonical operation | Public methods |")
				w.line("| --- | --- |")
				aliases = true
			}
			symbols := []string{}
			for _, m := range op.Methods() {
				symbols = append(symbols, "`"+g.Accessor+"()->"+m.PHPName+"()`")
			}
			w.line("| `" + op.ID + "` | " + strings.Join(symbols, ", ") + " |")
		}
	}
	if len(result.Excluded) > 0 {
		w.line("")
		w.line("## Excluded operations")
		w.line("")
		w.line("| Operation | Reason |")
		w.line("| --- | --- |")
		for _, e := range result.Excluded {
			w.line(fmt.Sprintf("| `%s` | %s |", e.ID, strings.ReplaceAll(e.Reason, "|", `\|`)))
		}
	}
	return w.b.String()
}

func uniqueSorted(values []string) []string {
	set := map[string]bool{}
	for _, value := range values {
		set[value] = true
	}
	result := make([]string, 0, len(set))
	for value := range set {
		result = append(result, value)
	}
	sort.Strings(result)
	return result
}

// isMultiple identifies encodings whose array inputs require element PHPDoc.
func isMultiple(encoding string) bool {
	return encoding == "records" || encoding == "collection" || encoding == "repeat" || encoding == "numbered" || encoding == "suffix-numbered" || encoding == "suffix-numbered-scalar"
}

// publicMethods expands input-only aliases without adding canonical operations.
func publicMethods(g effective.Group) []effective.Operation {
	var methods []effective.Operation
	for _, op := range g.Operations {
		methods = append(methods, op.Methods()...)
	}
	return methods
}
